package taxonomy.service

import kotlinx.serialization.json.jsonObject
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test
import taxonomy.dataset.ModelEvalResult
import taxonomy.operations.InMemoryRecipeKit
import taxonomy.operations.RecipeReference
import taxonomy.prompts.StackV2JudgeRecipe

/**
 * End-to-end assembly parity on a synthetic match: the Kotlin `TracePreparation.robustTrace` +
 * `StackV2JudgeRecipe.assemble` bytes equal the Python-generated bytes
 * (`rj.robust_trace` + `rref.with_reference` + `sj.system_for` + `rr.payload_bytes`) over the same
 * fixture: a question with non-ASCII, an arx JSON envelope on trace A, a `\r` and an em dash on
 * trace B, a rubric with a trailing newline, an empty option. Also pins the skip outcomes.
 */
class StackV2AssemblyGoldenTest {

    private val g = JudgeWiringFixtures.read("assembly_golden.json").jsonObject
    private val expected = g["expected"]!!.jsonObject
    private val options = JudgeWiringFixtures.strings(g, "options")

    private fun evalRow(model: String, output: String, pred: String?) = ModelEvalResult(
        questionId = 4242, modelName = model, category = "physics", questionText = JudgeWiringFixtures.str(g, "question_text"),
        options = options, gtAnswer = "Z", pred = pred, modelOutput = output, isCorrect = false
    )

    private fun kit(withAnchor: Boolean = true, withRef: Boolean = true) = InMemoryRecipeKit(
        anchorRubrics = mapOf(JudgeWiringFixtures.str(g, "anchor") to (JudgeWiringFixtures.str(g, "anchor_system_prompt") to JudgeWiringFixtures.str(g, "anchor_rubric"))),
        questionAnchor = if (withAnchor) mapOf(4242 to ("n00000001" to JudgeWiringFixtures.str(g, "anchor"))) else emptyMap(),
        references = if (withRef) mapOf(4242 to RecipeReference(JudgeWiringFixtures.str(g, "ref_letter"), JudgeWiringFixtures.str(g, "ref_text"))) else emptyMap()
    )

    private val params = StackV2JudgeRecipe.Params(JudgeWiringFixtures.str(g, "model"), (g["max_tokens"] as kotlinx.serialization.json.JsonPrimitive).content.toInt(), null)

    @Test
    fun `assembled bodies are byte-identical to the Python bytes`() {
        val stats = TracePreparation.Stats()
        val ta = TracePreparation.robustTrace(evalRow("a", JudgeWiringFixtures.str(g, "trace_a_output"), JudgeWiringFixtures.str(g, "trace_a_pred")), "RESOLVED", stats)
        val tb = TracePreparation.robustTrace(evalRow("b", JudgeWiringFixtures.str(g, "trace_b_output"), JudgeWiringFixtures.str(g, "trace_b_pred")), "RESOLVED", stats)
        assertEquals(JudgeWiringFixtures.str(expected, "trace_a"), ta)
        assertEquals(JudgeWiringFixtures.str(expected, "trace_b"), tb)
        assertTrue(tb.contains('\r'), "the CR inside trace B must survive (Python substitutes after trimming)")
        assertEquals(2, stats.resolvedInjected.get())

        val a = StackV2JudgeRecipe.assemble(kit(), 4242, JudgeWiringFixtures.str(g, "question_text"), ta, tb, params)
        assertTrue(a is StackV2JudgeRecipe.Assembly.Assembled)
        a as StackV2JudgeRecipe.Assembly.Assembled
        assertEquals(JudgeWiringFixtures.str(expected, "system"), a.system)
        assertEquals(JudgeWiringFixtures.str(expected, "user1"), a.user1)
        assertEquals(JudgeWiringFixtures.str(expected, "user2"), a.user2)
        assertArrayEquals(JudgeWiringFixtures.str(expected, "body1").toByteArray(Charsets.US_ASCII), a.body1)
        assertArrayEquals(JudgeWiringFixtures.str(expected, "body2").toByteArray(Charsets.US_ASCII), a.body2)
        assertEquals(JudgeWiringFixtures.str(expected, "sha1"), a.sha1)
        assertEquals(JudgeWiringFixtures.str(expected, "sha2"), a.sha2)
        assertEquals(JudgeWiringFixtures.str(g, "anchor"), a.anchor)
        assertEquals(JudgeWiringFixtures.str(g, "ref_letter"), a.refLetter)
        // every body byte is ASCII (ensure_ascii), and the body carries no temperature key
        assertTrue(a.body1.all { it in 0x20..0x7e })
        assertFalse(String(a.body1).contains("\"temperature\""))
    }

    @Test
    fun `a configured temperature literal is posted as a JSON float`() {
        val stats = TracePreparation.Stats()
        val ta = TracePreparation.robustTrace(evalRow("a", JudgeWiringFixtures.str(g, "trace_a_output"), "A"), "RESOLVED", stats)
        val tb = TracePreparation.robustTrace(evalRow("b", JudgeWiringFixtures.str(g, "trace_b_output"), "B"), "RESOLVED", stats)
        val a = StackV2JudgeRecipe.assemble(kit(), 4242, JudgeWiringFixtures.str(g, "question_text"), ta, tb, params.copy(temperature = 0.0)) as StackV2JudgeRecipe.Assembly.Assembled
        assertArrayEquals(JudgeWiringFixtures.str(expected, "body1_temperature_0").toByteArray(Charsets.US_ASCII), a.body1)
        assertTrue(String(a.body1).endsWith(", \"temperature\": 0.0}"))
        assertEquals("0.0", params.copy(temperature = 0.0).temperatureLabel)
        assertEquals("omitted", params.temperatureLabel)
    }

    @Test
    fun `bare prediction fallbacks match the Python port`() {
        val stats = TracePreparation.Stats()
        assertEquals(JudgeWiringFixtures.str(expected, "bare_pred_c"), TracePreparation.robustTrace(evalRow("x", "   ", "C"), "RESOLVED", stats))
        assertEquals(JudgeWiringFixtures.str(expected, "bare_no_pred"), TracePreparation.robustTrace(evalRow("x", "", null), "RESOLVED", stats))
        assertEquals(JudgeWiringFixtures.str(expected, "bare_out_of_range"), TracePreparation.robustTrace(evalRow("x", "", "K"), "RESOLVED", stats))
    }

    @Test
    fun `missing anchor or reference is a skip, never a fallback`() {
        val q = JudgeWiringFixtures.str(g, "question_text")
        val s1 = StackV2JudgeRecipe.assemble(kit(withAnchor = false), 4242, q, "a", "b", params)
        assertTrue(s1 is StackV2JudgeRecipe.Assembly.Skipped && (s1 as StackV2JudgeRecipe.Assembly.Skipped).reason.startsWith("no anchor"))
        val s2 = StackV2JudgeRecipe.assemble(kit(withRef = false), 4242, q, "a", "b", params)
        assertTrue(s2 is StackV2JudgeRecipe.Assembly.Skipped && (s2 as StackV2JudgeRecipe.Assembly.Skipped).reason.startsWith("no reference"))
        val noRubric = InMemoryRecipeKit(emptyMap(), mapOf(4242 to ("n1" to "Physics")), mapOf(4242 to RecipeReference("A", "x")))
        assertThrows(IllegalStateException::class.java) { StackV2JudgeRecipe.assemble(noRubric, 4242, q, "a", "b", params) }
    }

    @Test
    fun `kit hash is stable and changes with any row`() {
        val k1 = kit(); val k2 = kit()
        assertEquals(k1.kitHash, k2.kitHash)
        assertEquals(64, k1.kitHash.length)
        val k3 = InMemoryRecipeKit(k1.anchorRubrics, k1.questionAnchor, mapOf(4242 to RecipeReference("B", "other")))
        assertNotEquals(k1.kitHash, k3.kitHash)
        assertEquals("STACK-v2", k1.recipe)
        val fp = StackV2JudgeRecipe.deploymentFingerprint("grok-4-1-fast-non-reasoning", "2024-05-01-preview", 8192, "omitted", k1.kitHash)
        assertEquals(16, fp.length)
        assertNotEquals(fp, StackV2JudgeRecipe.deploymentFingerprint("grok-4-1-fast-non-reasoning", "2024-05-01-preview", 8192, "0.0", k1.kitHash))
    }
}
